import slugify from 'slugify';

/** Strip noisy whitespace / unicode junk from scraped text. */
export function cleanText(raw: string): string {
  return raw
    .replace(/\u00A0/g, ' ')           // non-breaking spaces
    .replace(/[\u200B-\u200D\uFEFF]/g, '') // zero-width chars
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')        // collapse runs of blank lines
    .replace(/[ \t]{2,}/g, ' ')        // collapse inline spaces
    .replace(/^ +| +$/gm, '')          // trim each line
    .trim();
}

/** Turn a title into a safe filename slug (max 80 chars). */
export function toSlug(title: string): string {
  return slugify(title, { lower: true, strict: true, trim: true }).slice(0, 80) || 'article';
}

/** Count words in a body text. */
export function wordCount(text: string): number {
  return text.trim().split(/\s+/).filter(Boolean).length;
}

/** Build a front-matter + body Markdown file string. */
export function buildMarkdown(fields: Record<string, unknown>, body: string): string {
  const fm = Object.entries(fields)
    .map(([k, v]) => `${k}: ${JSON.stringify(v)}`)
    .join('\n');
  return `---\n${fm}\n---\n\n${body}\n`;
}

/** Build an article file: frontmatter + <!-- BODY --> + extracted text. */
export function buildArticleMarkdown(
  fields: Record<string, unknown>,
  body: string,
): string {
  const fm = Object.entries(fields)
    .map(([k, v]) => `${k}: ${JSON.stringify(v)}`)
    .join('\n');
  return `---\n${fm}\n---\n\n<!-- BODY -->\n${body}\n`;
}

