/**
 * Reconstruct the legacy `id` frontmatter value the same way
 * article-store.ts's persistArticle originally derived it: the article's
 * date, site, and the deduped filename stem. The DB never stores this
 * string on its own (file_path is the source of truth for the stem), so it
 * is rebuilt deterministically rather than read back from the very file
 * this command may be repairing.
 */
function legacyArticleId(row: ArticleRow): string {
  const dateStr = (row.published_at ?? row.extracted_at).slice(0, 10);
  const filenameStem = basename(row.file_path).replace(/\.md$/, '');
  return `art-${dateStr}-${row.site}-${filenameStem}`;
}

